package com.primehr.learningdevelopment.participation.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="ld_nomination_route",uniqueConstraints=@UniqueConstraint(name="uk_ld_nomination_route_revision",columnNames={"agency_id","nomination_id","route_revision"}))
public class LdNominationRoute extends RspAuditedEntity {public enum Status{ACTIVE,RETURNED,COMPLETED,CANCELLED,SUPERSEDED}@Column(name="nomination_id",nullable=false,length=36)private String nominationId;@Column(name="route_revision",nullable=false)private int routeRevision;@Column(name="request_code",nullable=false,length=100)private String requestCode;@Column(name="business_unit_id",nullable=false)private Long businessUnitId;@Column(name="route_fingerprint",nullable=false,length=64)private String routeFingerprint;@Column(name="submitted_content_revision",nullable=false)private int submittedContentRevision;@Column(name="current_level",nullable=false)private int currentLevel;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="submitted_by",nullable=false,length=100)private String submittedBy;@Column(name="submitted_at",nullable=false)private Instant submittedAt;protected LdNominationRoute(){}public LdNominationRoute(String agency,String nomination,int revision,String request,Long unit,String fingerprint,int content,String actor,Instant at){super(agency);nominationId=requiredText(nomination,"nominationId");if(revision<1)throw new IllegalArgumentException("routeRevision must be positive");routeRevision=revision;requestCode=requiredText(request,"requestCode");businessUnitId=unit;routeFingerprint=requiredText(fingerprint,"routeFingerprint");submittedContentRevision=content;currentLevel=1;status=Status.ACTIVE;submittedBy=requiredText(actor,"actor");submittedAt=at;}public void advance(int level){currentLevel=level;}public void finish(Status value){status=value;}public String getNominationId(){return nominationId;}public int getRouteRevision(){return routeRevision;}public String getRequestCode(){return requestCode;}public Long getBusinessUnitId(){return businessUnitId;}public String getRouteFingerprint(){return routeFingerprint;}public int getSubmittedContentRevision(){return submittedContentRevision;}public int getCurrentLevel(){return currentLevel;}public Status getStatus(){return status;}public String getSubmittedBy(){return submittedBy;}public Instant getSubmittedAt(){return submittedAt;}}
